    return x ** 2

def numerical_derivative(f, x, h=1e-6):
    pass

quiz.solution:
def f(x):
    return x ** 2

def numerical_derivative(f, x, h=1e-6):
    return (f(x + h) - f(x - h)) / (2 * h)

print(numerical_derivative(f, 2))

