w = 0.0
eta = 0.1
for _ in range(10):
    w = w - eta * grad(w)
print(w)

codeExample.code:
# 用数值微分验证链式法则
# y = f(g(x)), f(u)=u^2, g(x)=2x+1
def g(x):
    return 2 * x + 1

def f(u):
    return u ** 2

# 由链式法则 dy/dx = f'(g(x)) * g'(x) = 2*g(x) * 2
def chain_derivative(x):
    return 2 * g(x) * 2

# 数值验证
def numeric(fn, x, h=1e-6):
    return (fn(x + h) - fn(x - h)) / (2 * h)

def full(x):
    return f(g(x))

x = 3.0
print('chain =', chain_derivative(x))   # 2*(7)*2 = 28
print('numeric =', round(numeric(full, x), 6))  # ≈ 28

